import{_ as e}from"./chunks/dispatch-week.BMCYSnKC.js";import{_ as t,o as r,c as l,a2 as s}from"./chunks/framework.BjkiRu3Q.js";const f=JSON.parse('{"title":"Πρόγραμμα αναθέσεων","description":"","frontmatter":{},"headers":[],"relativePath":"el/plus/dispatch-schedule.md","filePath":"el/plus/dispatch-schedule.md"}'),o={name:"el/plus/dispatch-schedule.md"};function i(n,a,h,c,p,d){return r(),l("div",null,[...a[0]||(a[0]=[s('<h1 id="προγραμμα-αναθεσεων" tabindex="-1">Πρόγραμμα αναθέσεων <a class="header-anchor" href="#προγραμμα-αναθεσεων" aria-label="Permalink to &quot;Πρόγραμμα αναθέσεων&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>Πηγαίος κώδικας TransferBook+ v0.7.9. Το παρόν είναι τοπικό προσχέδιο προς έλεγχο, όχι επιβεβαίωση διαθεσιμότητας στην παραγωγή. Ελέγξτε την εγκατεστημένη έκδοση και τα δικαιώματά σας.</p></div><h2 id="εικονογραφημενη-προβολη" tabindex="-1">Εικονογραφημένη προβολή <a class="header-anchor" href="#εικονογραφημενη-προβολη" aria-label="Permalink to &quot;Εικονογραφημένη προβολή&quot;">​</a></h2><p><a href="/screenshots/v0.7.11/dispatch-week.png"><img src="'+e+'" alt="Εβδομαδιαία προβολή αναθέσεων: χρησιμοποιήστε τα Day, Week ή Month, την επιλογή ημερομηνίας και το φίλτρο κατάστασης."></a></p><p><em>Επιλέξτε την εικόνα για προβολή στο αρχικό της μέγεθος. Επιστρέψτε με το κουμπί Πίσω του προγράμματος περιήγησης.</em></p><p><em>Εβδομαδιαία προβολή αναθέσεων: χρησιμοποιήστε τα Day, Week ή Month, την επιλογή ημερομηνίας και το φίλτρο κατάστασης.</em></p><p>Λήψη από περιβάλλον δοκιμών, TransferBook+ v0.7.11· αγγλικό περιβάλλον. Ενδεικτικά δοκιμαστικά στοιχεία. Η εικόνα δεν αποδεικνύει διαθεσιμότητα στην παραγωγή. Έχουν καλυφθεί αναγνωριστικά στοιχεία.</p><h2 id="σκοπος-και-προσβαση" tabindex="-1">Σκοπός και πρόσβαση <a class="header-anchor" href="#σκοπος-και-προσβαση" aria-label="Permalink to &quot;Σκοπός και πρόσβαση&quot;">​</a></h2><p>Το ημερολόγιο αναθέσεων παρέχει προβολές ημέρας, εβδομάδας και μήνα για έλεγχο του φόρτου από εξουσιοδοτημένο χειριστή.</p><h2 id="διαδικασια" tabindex="-1">Διαδικασία <a class="header-anchor" href="#διαδικασια" aria-label="Permalink to &quot;Διαδικασία&quot;">​</a></h2><ol><li>Ανοίξτε <strong>Dispatch Timeline &amp; Daily Schedule</strong> ή την προβολή ημερολογίου.</li><li>Επιλέξτε ημέρα, εβδομάδα ή μήνα, τη σχετική περίοδο και την περιοχή.</li><li>Χρησιμοποιήστε τα φίλτρα <strong>All statuses</strong>, <strong>Quote required</strong>, <strong>Tour acceptance pending</strong>, <strong>Dispatch review</strong>, <strong>Assigned / In transit</strong> ή <strong>Completed / Cancelled</strong>.</li><li>Ελέγξτε τις προγραμματισμένες παραλαβές χρονικά και ανοίξτε τις λεπτομέρειες πριν από ανάθεση.</li><li>Ελέγξτε οδηγό, όχημα, χωρητικότητα, περιοχή και επικαλύψεις πριν από ανάθεση μέσω των εγκεκριμένων εργαλείων.</li></ol><h2 id="αναμενομενο-αποτελεσμα" tabindex="-1">Αναμενόμενο αποτέλεσμα <a class="header-anchor" href="#αναμενομενο-αποτελεσμα" aria-label="Permalink to &quot;Αναμενόμενο αποτέλεσμα&quot;">​</a></h2><p>Η επιλεγμένη περίοδος και τα φίλτρα εμφανίζουν τις αντίστοιχες κρατήσεις. Οι εκκρεμείς προσφορές ή έλεγχοι δεν σημαίνουν ετοιμότητα ανάθεσης.</p><h2 id="αντιμετωπιση-προβληματων" tabindex="-1">Αντιμετώπιση προβλημάτων <a class="header-anchor" href="#αντιμετωπιση-προβληματων" aria-label="Permalink to &quot;Αντιμετώπιση προβλημάτων&quot;">​</a></h2><p>Ελέγξτε περιοχή, περίοδο και φίλτρο αν λείπει διαδρομή. Αν απορρίπτεται ανάθεση, επιλύστε τις συγκρούσεις. Δείτε την <a href="/el/plus/assignments.html">ανάθεση οδηγού και οχήματος</a>.</p><h2 id="αλλαγες-που-περιγραφονται-στην-v0-7-14" tabindex="-1">Αλλαγές που περιγράφονται στην v0.7.14 <a class="header-anchor" href="#αλλαγες-που-περιγραφονται-στην-v0-7-14" aria-label="Permalink to &quot;Αλλαγές που περιγράφονται στην v0.7.14&quot;">​</a></h2><p>Η δημοσιευμένη έκδοση περιγράφει διορθώσεις διάταξης για διαφορετικές οθόνες, βελτιωμένη πλοήγηση ημερομηνιών και ημερολόγιο, εσωτερικές σημειώσεις αναθέσεων και εξουσιοδοτημένες παρακάμψεις με υποχρεωτική αιτιολόγηση ελέγχου. Ελέγξτε το ημερολόγιο και τα στοιχεία ανάθεσης πριν ενεργήσετε. Χρησιμοποιήστε παράκαμψη μόνο με την κατάλληλη εξουσιοδότηση, καταγράψτε τον πραγματικό λόγο και επαληθεύστε το αποτέλεσμα. Τα ακριβή χειριστήρια και δικαιώματα χρειάζονται αποδοχή ανά έκδοση. Η εικόνα v0.7.11 παραμένει ιστορική.</p><p>Δείτε <a href="/el/release-notes/">Σημειώσεις εκδόσεων</a>.</p><h2 id="ελεγχος-αναθεσης-v0-7-26" tabindex="-1">Έλεγχος ανάθεσης v0.7.26 <a class="header-anchor" href="#ελεγχος-αναθεσης-v0-7-26" aria-label="Permalink to &quot;Έλεγχος ανάθεσης v0.7.26&quot;">​</a></h2><p>Ελέγξτε πλήρες διάστημα ανάθεσης, περιθώριο, βάρδια/απουσία οδηγού, συντήρηση και χωρητικότητα επιβατών/αποσκευών. Ταυτόχρονες αναθέσεις μπορεί να απορριφθούν λόγω κλειδώματος πόρων· ανανεώστε και επιλύστε τη σύγκρουση. Τα σκέλη επιστροφής είναι ανεξάρτητα. Για προτεινόμενη αλλαγή παραλαβής ελέγξτε τεκμήριο και όρια ημερομηνίας/νυχτερινού ναύλου πριν την έγκριση· ελέγξτε αποθηκευμένο πρόγραμμα. Δείτε <a href="/el/plus/arrival-intelligence.html">Αφίξεις</a> και <a href="/el/plus/subcontractors.html">Υπεργολάβους</a>.</p>',20)])])}const _=t(o,[["render",i]]);export{f as __pageData,_ as default};
